    private async Task LoadApprovedClusterBackupsAsync(ClusterDefinition cluster,ClusterBackupPageState state)
    {
        if(state.Loading||state.Busy)return;state.Loading=true;try{state.Inventory=await client!.CallAsync<ManagedClusterBackupInventory>("managed-cluster-backups-read",cluster.Id,TimeSpan.FromSeconds(8),lifetime.Token);}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Loading=false;if(selectedCluster==cluster.Id&&managementTab==3&&!lifetime.IsCancellationRequested)Render();}
    }
    private async Task SaveApprovedClusterScopeAsync(ClusterDefinition cluster,ClusterBackupPageState state,List<Guid> maps,bool shared,ManagedBackupPolicy? policy=null)
    {
        state.Busy=true;Render();try{if(designPreview){if(maps.Count==0)throw new ArgumentException("Include at least one map.");state.Inventory=state.Inventory! with{Maps=maps,IncludeShared=shared,Policy=policy??state.Inventory!.Policy};}else state.Inventory=(await RunManagedScreenJobAsync(cluster.Id,"managed-cluster-backup-preferences",new ManagedClusterBackupPreferences(cluster.Id,policy??state.Inventory?.Policy??new(),maps,shared))).Deserialize<ManagedClusterBackupInventory>();state.Notice="Backup scope and schedule saved.";}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Busy=false;Render();}
    }
    private async Task CreateApprovedClusterBackupAsync(ClusterDefinition cluster,ClusterBackupPageState state)
    {
        var body=new StackPanel{Margin=new(26),Spacing=22};body.Children.Add(Label("Create Cluster Backup",26,true));var name=EditorText("Manual backup","Cluster backup name");body.Children.Add(name);var dialog=ManagementDialog("Create Cluster Backup",body);body.Children.Add(EditorButton("Create Cluster Backup",()=>dialog.Close(true),true));if(!await dialog.ShowDialog<bool>(this))return;
        state.Busy=true;Render();try{if(designPreview)throw new InvalidOperationException("Reference preview has no game archives.");state.Inventory=(await RunManagedScreenJobAsync(cluster.Id,"managed-cluster-backup-create",new ManagedClusterBackupCreate(cluster.Id,name.Text??""))).Deserialize<ManagedClusterBackupInventory>();state.Notice="Cluster backup created and verified.";}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Busy=false;Render();}
    }
    private async Task DeleteApprovedClusterBackupAsync(ClusterDefinition cluster,ClusterBackupPageState state,ManagedClusterBackupEntry entry)
    {
        if(!await ConfirmManagementAsync("Delete cluster backup?",$"Delete “{entry.Name}” and its captured map/transfer archives?","Delete"))return;state.Busy=true;Render();try{state.Inventory=(await RunManagedScreenJobAsync(cluster.Id,"managed-cluster-backup-delete",new ManagedClusterBackupSelection(cluster.Id,entry.Id,true))).Deserialize<ManagedClusterBackupInventory>();state.Notice="Cluster backup deleted.";}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Busy=false;Render();}
    }
    private async Task RestoreApprovedClusterBackupAsync(ClusterDefinition cluster,ClusterBackupPageState state,ManagedClusterBackupEntry entry)
    {
        if(!await ConfirmManagementAsync("Restore cluster backup?",$"Restore “{entry.Name}” for {entry.Point.Maps.Count} maps{(entry.IncludesShared?" and shared transfer data":"")}? All cluster maps must be stopped. Server settings are preserved.","Restore"))return;state.Busy=true;Render();try{var result=(await RunManagedScreenJobAsync(cluster.Id,"managed-cluster-backup-restore",new ManagedClusterBackupSelection(cluster.Id,entry.Id,true))).Deserialize<ClusterRestoreRecord>()!;state.Notice=result.Phase==ClusterRestorePhase.Restored?"Cluster backup restored. Maps remain stopped.":"Restore requires review: "+result.Phase;}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Busy=false;Render();}
    }
